  '/shipping-returns': { eyebrow: 'The details', title: 'Shipping & returns.', intro: 'We keep delivery personal so the details are right for you.', groups: [{ q: 'Delivery', a: 'Delivery charges will be confirmed on WhatsApp. We will share timing and any applicable charges before dispatching your order.' }, { q: 'Size exchanges', a: initialSettings.returnPolicy }, { q: 'Damaged or incorrect items', a: 'Please message us within 48 hours of receiving your order with a photo and your order details so we can make it right.' }] },
  '/size-guide': { eyebrow: 'Find your fit', title: 'Your easiest size guide.', intro: 'Khussa should feel snug at first; leather relaxes gently with wear.', groups: [{ q: 'If you are between sizes', a: 'Choose the larger size, especially if you prefer a little room or plan to wear socks.' }, { q: 'Quick measuring method', a: 'Stand on a sheet of paper, mark the back of your heel and the tip of your longest toe, then measure the distance in centimetres.' }, { q: 'Our standard range', a: 'Most styles are available in EU sizes 36–42. Message us for guidance if you are unsure.' }] },
  '/privacy': { eyebrow: 'Good to know', title: 'Privacy policy.', intro: 'We keep your details for the things you asked us to do—nothing more.', groups: [{ q: 'What we collect', a: 'When you order, we collect your name, phone, address and city so we can confirm and deliver your purchase. Newsletter signups are stored so we can send future updates if an email service is connected.' }, { q: 'How we use it', a: 'We use your details to communicate about your order, provide support and improve the store. We do not sell customer information.' }] },
  '/terms': { eyebrow: 'The fine print', title: 'Terms & conditions.', intro: 'The simple version of how Gifto Khussa works.', groups: [{ q: 'Orders', a: 'An order is considered pending until we confirm product availability, size and delivery details with you on WhatsApp.' }, { q: 'Pricing', a: 'All prices are displayed in PKR. Delivery charges are confirmed separately on WhatsApp.' }, { q: 'Product character', a: 'Hand-finished items can show small variations in stitch, texture and colour. These are part of their individual character.' }] }
