  const [tab, setTab] = useState(window.location.pathname.includes('settings') ? 'settings' : window.location.pathname.includes('orders') ? 'orders' : window.location.pathname.includes('products') ? 'products' : 'dashboard');
  const [credentials, setCredentials] = useState({ email: 'admin@giftokhussa.com', password: '' });
  const [saved, setSaved] = useState(false);
  const orders = readJSON(ORDERS_KEY, []);
  const newsletter = readJSON(NEWSLETTER_KEY, []);
  const login = event => { event.preventDefault(); if (credentials.email === 'admin@giftokhussa.com' && credentials.password === 'G1fto!Lahore#2026') { setLoggedIn(true); saveJSON('gifto-admin-session', true); } };
  if (!loggedIn) return <div className="admin-login page"><div className="admin-login-card"><Wordmark /><p className="eyebrow">Private workspace</p><h1>Welcome back, <em>Hasham.</em></h1><p>Manage your products, orders and the details your customers see.</p><form onSubmit={login}><input type="email" placeholder="Admin email" value={credentials.email} onChange={event => setCredentials({ ...credentials, email: event.target.value })} /><input type="password" placeholder="Temporary password" value={credentials.password} onChange={event => setCredentials({ ...credentials, password: event.target.value })} /><button className="button button-primary button-full" type="submit">Enter admin <ArrowRight size={16} /></button></form><small>Demo password: G1fto!Lahore#2026. Change it before production.</small></div></div>;
  const updateSetting = (key, value) => setSettings(current => ({ ...current, [key]: value }));
